    "code_snippets_v2/lazy_init_c/client.py": """"API client that reads config dynamically (no import-time snapshot)."""

from config import get_config


def _get_client_cfg():
    """Always retrieve the current config dict from config.get_config()."""
    return get_config()


def get_api_key():
    """Return the API key the client uses (reads config at call time)."""
    return _get_client_cfg()["api_key"]


def get_base_url():
    """Return the base URL the client uses (reads config at call time)."""
    return _get_client_cfg()["base_url"]


def build_headers():
